package com.aster.probe;
import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import java.net.*;
import java.util.concurrent.*;
public final class ProbeActivity extends Activity {
 private String fetch(String url,boolean load)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);try(java.io.InputStream in=c.getInputStream()){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buf=new byte[32768];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(load){for(int i=0;i<n;i++)if(buf[i]!=0x5a)throw new Exception("Payload mismatch");}else bytes.write(buf,0,n);}if(load&&total!=2097152)throw new Exception("Truncated transfer: "+total);return load?"OK":bytes.toString("UTF-8");}finally{c.disconnect();}}
 private void udp(String url)throws Exception{URL parsed=new URL(url);try(DatagramSocket socket=new DatagramSocket()){socket.setSoTimeout(1000);byte[] message="UDP_CHECK".getBytes();socket.send(new DatagramPacket(message,message.length,InetAddress.getByName(parsed.getHost()),parsed.getPort()));DatagramPacket reply=new DatagramPacket(new byte[64],64);socket.receive(reply);if(!new String(reply.getData(),0,reply.getLength()).equals("UDP_CHECK"))throw new Exception("UDP mismatch");}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);String url=getIntent().getStringExtra("url");boolean load=getIntent().getBooleanExtra("load",false);int seconds=getIntent().getIntExtra("duration",0);new Thread(()->{String result,stats="";ExecutorService pool=Executors.newFixedThreadPool(10);try{if(getIntent().getBooleanExtra("dns",false)){InetAddress[] resolved=InetAddress.getAllByName("example.com");if(resolved.length==0)throw new Exception("DNS returned no addresses");android.util.Log.i("AsterProbe","DNS_PASS "+resolved[0].getHostAddress());}long start=System.nanoTime(),bytes=0,maxSmall=0;int rounds=0,udpCount=0,udpLost=0;if(load){do{long round=System.nanoTime();java.util.List<Future<String>> tasks=new java.util.ArrayList<>();for(int i=0;i<16;i++)tasks.add(pool.submit(()->fetch(url+"load",true)));Future<Long> small=pool.submit(()->{long at=System.nanoTime();if(!fetch(url,false).contains("ASTER_TUNNEL_OK"))throw new Exception("Small request failed");return (System.nanoTime()-at)/1000000;});Future<Integer> datagrams=pool.submit(()->{int lost=0,consecutive=0;for(int i=0;i<8;i++){try{udp(url);consecutive=0;}catch(java.net.SocketTimeoutException e){lost++;if(++consecutive>=3)throw new Exception("UDP stalled for three consecutive probes",e);}Thread.sleep(100);}return lost;});for(int i=0;i<tasks.size();i++)try{tasks.get(i).get(45,TimeUnit.SECONDS);}catch(Exception e){throw new Exception("Download "+i,e);}maxSmall=Math.max(maxSmall,small.get(20,TimeUnit.SECONDS));udpLost+=datagrams.get(20,TimeUnit.SECONDS);udpCount+=8;bytes+=33554432L;rounds++;android.util.Log.i("AsterProbe","LOAD_PROGRESS "+(bytes/1048576)+"MiB elapsed="+((System.nanoTime()-start)/1000000000)+"s smallMax="+maxSmall+"ms UDP="+udpCount+" lost="+udpLost);if(seconds>0){long remaining=8000-(System.nanoTime()-round)/1000000;if(remaining>0)Thread.sleep(remaining);}}while(seconds>0&&((System.nanoTime()-start)/1000000000<seconds||bytes<1073741824L));if(udpLost*100>udpCount*5)throw new Exception("UDP loss exceeds 5%: "+udpLost+"/"+udpCount);stats="LOAD_PASS bytes="+bytes+" durationMs="+((System.nanoTime()-start)/1000000)+" shortHttpMaxMs="+maxSmall+" UDP="+udpCount+" lost="+udpLost+" rounds="+rounds;android.util.Log.i("AsterProbe",stats);}result=fetch(url,false);}catch(Exception e){android.util.Log.e("AsterProbe","Transfer failed",e);result="FAIL: "+e.toString();}finally{pool.shutdownNow();}android.util.Log.i("AsterProbe",result);sendBroadcast(new Intent("com.aster.vpn.PROBE_RESULT").setPackage("com.aster.vpn").putExtra("result",result).putExtra("stats",stats));runOnUiThread(this::finish);}).start();}
}
